// Package hwstatus answers "what is known about this hardware": the status of
// a product/board/BIOS/EC-firmware combination from the embedded table
// results.tsv, generated by `go generate` (internal/genresults) from
// befunde/RESULTS.md of this repository (the single source; never edit
// results.tsv by hand).
//
// The status says what was tested, not what the software can do:
//
//	validated     TESTSPEC T1-T3 PASS on at least two devices
//	tested        one TESTSPEC run on one device, bundle published
//	experimental  loads, no TESTSPEC run; writes only where the driver allows
//	unknown       not in the table
package hwstatus

import (
	"bufio"
	_ "embed"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// Status is one of the four hardware status values.
type Status string

const (
	Validated    Status = "validated"
	Tested       Status = "tested"
	Experimental Status = "experimental"
	Unknown      Status = "unknown"
)

// Verified is the compatibility reading of a status for the API's
// "verified" field: true only for validated and tested.
func (s Status) Verified() bool { return s == Validated || s == Tested }

// Valid reports whether s is one of the four values.
func (s Status) Valid() bool {
	switch s {
	case Validated, Tested, Experimental, Unknown:
		return true
	}
	return false
}

// Entry is one row of the table. "*" in BIOS or EC matches any value.
type Entry struct {
	Product string `json:"product"`
	Board   string `json:"board"`
	BIOS    string `json:"bios"`
	EC      string `json:"ec"`
	Status  Status `json:"status"`
	// Origin: "own" (measured on the reference device), "upstream" (the
	// driver author's statement, not tested by us), "report" (user report,
	// not tested). RESULTS.md spells them eigen/upstream/Bericht.
	Origin string `json:"origin"`
	Date   string `json:"date"`
	Note   string `json:"note"` // German, as in RESULTS.md
}

// Meta describes where the embedded table came from.
type Meta struct {
	Source string `json:"source"`
	// SourceTableSHA256 covers only the table between the hwstatus markers
	// of RESULTS.md (definition in internal/tablesum), not the whole file.
	SourceTableSHA256 string `json:"source_table_sha256"`
	Generated         string `json:"generated"`
}

//go:generate go run ./internal/genresults ../../../befunde/RESULTS.md results.tsv

//go:embed results.tsv
var embedded string

var (
	table []Entry
	meta  Meta
)

func init() {
	t, m, err := Parse(embedded)
	if err != nil {
		// The test suite parses the embedded file; a broken table never ships.
		panic("hwstatus: embedded results.tsv: " + err.Error())
	}
	table, meta = t, m
}

// Table returns a copy of the embedded table.
func Table() []Entry { return append([]Entry(nil), table...) }

// Source returns the provenance of the embedded table.
func Source() Meta { return meta }

var origins = map[string]string{"eigen": "own", "own": "own", "upstream": "upstream", "bericht": "report", "report": "report"}

// Parse reads the generated TSV: "#" lines carry the metadata, every other
// non-empty line is one row with 8 tab-separated fields.
func Parse(s string) ([]Entry, Meta, error) {
	var out []Entry
	var m Meta
	sc := bufio.NewScanner(strings.NewReader(s))
	n := 0
	for sc.Scan() {
		n++
		line := strings.TrimRight(sc.Text(), "\r")
		if strings.TrimSpace(line) == "" {
			continue
		}
		if strings.HasPrefix(line, "#") {
			k, v, ok := strings.Cut(strings.TrimSpace(strings.TrimPrefix(line, "#")), ":")
			if !ok {
				continue
			}
			v = strings.TrimSpace(v)
			switch strings.TrimSpace(k) {
			case "source":
				m.Source = v
			case "source-table-sha256":
				m.SourceTableSHA256 = v
			case "generated":
				m.Generated = v
			}
			continue
		}
		f := strings.Split(line, "\t")
		if len(f) != 8 {
			return nil, m, fmt.Errorf("line %d: %d fields, want 8", n, len(f))
		}
		for i := range f {
			f[i] = strings.TrimSpace(f[i])
		}
		e := Entry{Product: f[0], Board: f[1], BIOS: f[2], EC: f[3], Status: Status(f[4]), Date: f[6], Note: f[7]}
		if e.Product == "" || e.Board == "" || e.BIOS == "" || e.EC == "" {
			return nil, m, fmt.Errorf("line %d: empty key field", n)
		}
		if !e.Status.Valid() {
			return nil, m, fmt.Errorf("line %d: unknown status %q", n, f[4])
		}
		o, ok := origins[strings.ToLower(f[5])]
		if !ok {
			return nil, m, fmt.Errorf("line %d: unknown origin %q", n, f[5])
		}
		e.Origin = o
		if e.Status.Verified() && o != "own" {
			// validated/tested are TESTSPEC results of this project; a
			// statement of the driver author or a user report is
			// experimental at most (the driver flag is a write gate only)
			return nil, m, fmt.Errorf("line %d: status %s needs origin eigen/own, not %q", n, e.Status, f[5])
		}
		out = append(out, e)
	}
	if err := sc.Err(); err != nil {
		return nil, m, err
	}
	if len(out) == 0 {
		return nil, m, fmt.Errorf("no rows")
	}
	if m.Source == "" || m.Generated == "" {
		return nil, m, fmt.Errorf("source or generated line missing")
	}
	return out, m, nil
}

// Identity is the key of a lookup plus the DMI fields `identify` reports.
type Identity struct {
	Product      string `json:"product_name"`
	Board        string `json:"board_name"`
	BoardVersion string `json:"board_version"`
	SysVendor    string `json:"sys_vendor"`
	BIOS         string `json:"bios_version"`
	BIOSDate     string `json:"bios_date"`
	BIOSRelease  string `json:"bios_release"`
	EC           string `json:"ec_firmware_release"`
}

// ReadIdentity reads <sysRoot>/class/dmi/id/*. Missing files leave the
// field empty; nothing here writes.
func ReadIdentity(sysRoot string) Identity {
	rd := func(name string) string {
		b, err := os.ReadFile(filepath.Join(sysRoot, "class", "dmi", "id", name))
		if err != nil {
			return ""
		}
		return strings.TrimSpace(string(b))
	}
	return Identity{
		Product:      rd("product_name"),
		Board:        rd("board_name"),
		BoardVersion: rd("board_version"),
		SysVendor:    rd("sys_vendor"),
		BIOS:         rd("bios_version"),
		BIOSDate:     rd("bios_date"),
		BIOSRelease:  rd("bios_release"),
		EC:           rd("ec_firmware_release"),
	}
}

// Key renders the lookup key "N5 PRO / F8NAA / BIOS 1.05 / EC 0.14".
func (id Identity) Key() string {
	or := func(s string) string {
		if s == "" {
			return "?"
		}
		return s
	}
	return fmt.Sprintf("%s / %s / BIOS %s / EC %s", or(id.Product), or(id.Board), or(id.BIOS), or(id.EC))
}

// Result is the answer for one machine and profile.
type Result struct {
	Status Status `json:"status"`
	Key    string `json:"key"`             // the machine's key (Identity.Key)
	Entry  *Entry `json:"entry,omitempty"` // the matching row; nil = no row
	Reason string `json:"reason"`          // one English sentence
}

// Lookup finds the row for id: an exact row (all four fields) wins over a
// row with "*" in BIOS and/or EC; nothing matching is Unknown.
func Lookup(id Identity) Result {
	return lookupIn(table, id)
}

func lookupIn(t []Entry, id Identity) Result {
	r := Result{Status: Unknown, Key: id.Key()}
	best, bestScore := -1, -1
	for i, e := range t {
		if e.Product != id.Product || e.Board != id.Board {
			continue
		}
		score := 0
		switch {
		case e.BIOS == id.BIOS && id.BIOS != "":
			score += 2
		case e.BIOS == "*":
		default:
			continue
		}
		switch {
		case e.EC == id.EC && id.EC != "":
			score++
		case e.EC == "*":
		default:
			continue
		}
		if score > bestScore {
			best, bestScore = i, score
		}
	}
	if best < 0 {
		r.Reason = "this product/board/BIOS/EC firmware combination is not in the hardware results table"
		return r
	}
	e := t[best]
	r.Entry = &e
	r.Status = e.Status
	switch e.Origin {
	case "upstream":
		r.Reason = fmt.Sprintf("%s per the driver author (upstream), not tested by this project", e.Status)
	case "report":
		r.Reason = fmt.Sprintf("%s from a user report, not tested by this project", e.Status)
	default:
		r.Reason = fmt.Sprintf("%s on the reference device", e.Status)
	}
	return r
}

// ForProfile is the hardware status of a profile on this machine. Only the
// n5pro profile has hardware results; the generic chips and monitor are
// unknown by definition (documentation only / no fan control).
func ForProfile(profileName string, id Identity) Result {
	if profileName != "n5pro" {
		reason := "no hardware results for this profile (from documentation, untested)"
		if profileName == "monitor" {
			reason = "monitoring only, no fan control"
		}
		return Result{Status: Unknown, Key: id.Key(), Reason: reason}
	}
	r := Lookup(id)
	if r.Entry != nil && id.Product != "N5 PRO" {
		r.Reason += "; the n5pro channel table is measured on the N5 PRO only"
	}
	return r
}

// Describe is the one-line text for CLI output and logs.
func (r Result) Describe() string {
	return fmt.Sprintf("%s (%s: %s)", r.Status, r.Key, r.Reason)
}
